#include <vector>
#include <queue>
#include <tuple>

class Solution {
public:
    int minTimeToReachTarget(int n, std::vector<std::vector<int>>& edges, int maxPower) {
        std::vector<std::vector<std::tuple<int, int, int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2], e[3]});
            adj[e[1]].push_back({e[0], e[2], e[3]});
        }
        std::vector<std::vector<int>> dist(n, std::vector<int>(maxPower + 1, 1e9));
        dist[0][maxPower] = 0;
        using State = std::tuple<int, int, int>; // time, u, power
        std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
        pq.push({0, 0, maxPower});
        while (!pq.empty()) {
            auto [t, u, p] = pq.top();
            pq.pop();
            if (u == n - 1) return t;
            if (t > dist[u][p]) continue;
            for (auto& [v, edgeTime, edgePower] : adj[u]) {
                if (p >= edgePower) {
                    int np = p - edgePower;
                    int nt = t + edgeTime;
                    if (nt < dist[v][np]) {
                        dist[v][np] = nt;
                        pq.push({nt, v, np});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minTimeToReachTarget(int n, int[][] edges, int maxPower) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2], e[3]});
            adj.get(e[1]).add(new int[]{e[0], e[2], e[3]});
        }
        int[][] dist = new int[n][maxPower + 1];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][maxPower] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0, maxPower});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int t = top[0], u = top[1], p = top[2];
            if (u == n - 1) return t;
            if (t > dist[u][p]) continue;
            for (int[] edge : adj.get(u)) {
                int v = edge[0], edgeTime = edge[1], edgePower = edge[2];
                if (p >= edgePower) {
                    int np = p - edgePower;
                    int nt = t + edgeTime;
                    if (nt < dist[v][np]) {
                        dist[v][np] = nt;
                        pq.offer(new int[]{nt, v, np});
                    }
                }
            }
        }
        return -1;
    }
}

